// counts, the daily cap, and the pace of the GitHub actions.
func (q *Queries) ListRunsSince(ctx context.Context, since time.Time) ([]ListRunsSinceRow, error) {
	rows, err := q.db.QueryContext(ctx, listRunsSince, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRunsSinceRow{}
	for rows.Next() {
		var i ListRunsSinceRow
		if err := rows.Scan(
			&i.ID,
			&i.MatchID,
			&i.RoutineID,
			&i.ItemID,
			&i.Runner,
			&i.Status,
			&i.Outcome,
			&i.Manual,
			&i.BudgetReserved,
			&i.BudgetUnit,
			&i.Cost,
			&i.TokensIn,
			&i.TokensOut,
			&i.CacheReadTokens,
			&i.QueuedAt,
			&i.StartedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTries = `-- name: ListTries :many
SELECT item_id, reset_at FROM autopilot_tries WHERE routine_id = ?1
`

type ListTriesRow struct {
	ItemID  int64
	ResetAt time.Time
}

// ListTries returns when Try again last reset each of a routine's counts.
func (q *Queries) ListTries(ctx context.Context, routineID int64) ([]ListTriesRow, error) {
	rows, err := q.db.QueryContext(ctx, listTries, routineID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTriesRow{}
	for rows.Next() {
		var i ListTriesRow
		if err := rows.Scan(&i.ItemID, &i.ResetAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

