const upsertTries = `-- name: UpsertTries :exec
INSERT INTO autopilot_tries (routine_id, item_id, reset_at)
VALUES (?1, ?2, ?3)
ON CONFLICT (routine_id, item_id) DO UPDATE SET reset_at = excluded.reset_at
`

type UpsertTriesParams struct {
	RoutineID int64
	ItemID    int64
	ResetAt   time.Time
}

// UpsertTries records that Try again reset a routine's count of tries on an item.
func (q *Queries) UpsertTries(ctx context.Context, arg UpsertTriesParams) error {
	_, err := q.db.ExecContext(ctx, upsertTries, arg.RoutineID, arg.ItemID, arg.ResetAt)
	return err
}
